    dataset_version_id INTEGER NOT NULL,
    name VARCHAR NOT NULL,
    description VARCHAR,
    repetitions INTEGER NOT NULL,
    metadata JSONB NOT NULL,
    project_name VARCHAR,
    created_at TIMESTAMP DEFAULT (CURRENT_TIMESTAMP) NOT NULL,
