        ON DELETE CASCADE,
    CONSTRAINT fk_experiments_dataset_version_id_dataset_versions
        FOREIGN KEY (dataset_version_id)
        REFERENCES dataset_versions (id)
        ON DELETE CASCADE,
    CONSTRAINT fk_experiments_user_id_users
        FOREIGN KEY (user_id)
        REFERENCES users (id)
        ON DELETE SET NULL
);

